/// Popüler tarif veri modeli ve 144 tarif verisi
library;

class PopularRecipe {
  final String title;
  final String difficulty;
  final int prepTime;
  final int cookTime;
  final int ingredientCount;
  final String description;

  const PopularRecipe({
    required this.title,
    required this.difficulty,
    this.prepTime = 0,
    required this.cookTime,
    required this.ingredientCount,
    required this.description,
  });

  int get effectivePrepTime {
    if (prepTime > 0) return prepTime;
    if (difficulty == 'Kolay') return 10;
    if (difficulty == 'Orta') return 20;
    return 30;
  }
}

